"""Private GCS adapter. Object keys are generated by the application, never by clients."""

from __future__ import annotations

import asyncio
from typing import Any


class GcsDataboxStorage:
    def __init__(self, bucket_name: str | None = None) -> None:
        if not bucket_name:
            raise RuntimeError("DATABOX_GCS_BUCKET or GCS_BUCKET_NAME is required for GCS storage")
        self._bucket_name = bucket_name
        self._client: Any | None = None

    def _bucket(self) -> Any:
        if self._client is None:
            from google.cloud import storage

            self._client = storage.Client()
        return self._client.bucket(self._bucket_name)

    async def put(self, key: str, data: bytes, content_type: str) -> None:
        blob = self._bucket().blob(key)

        def _upload() -> None:
            with blob.open("wb", content_type=content_type) as handle:
                view = memoryview(data)
                for offset in range(0, len(view), 64 * 1024):
                    handle.write(view[offset : offset + 64 * 1024])

        await asyncio.to_thread(_upload)

    async def read_chunks(self, key: str, chunk_size: int = 64 * 1024):
        blob = self._bucket().blob(key)

        def _open():
            if not blob.exists():
                raise FileNotFoundError(key)
            return blob.open("rb")

        handle = await asyncio.to_thread(_open)
        try:
            while True:
                chunk = await asyncio.to_thread(handle.read, chunk_size)
                if not chunk:
                    break
                yield chunk
        finally:
            await asyncio.to_thread(handle.close)

    async def get(self, key: str) -> bytes:
        parts: list[bytes] = []
        async for chunk in self.read_chunks(key):
            parts.append(chunk)
        return b"".join(parts)

    async def delete(self, key: str) -> None:
        blob = self._bucket().blob(key)

        def _delete() -> None:
            if blob.exists():
                blob.delete()

        await asyncio.to_thread(_delete)
